MAP
    NAME "SS_MAP_RFRE_MEDIDORES_RF"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_medidores_rf.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_RFRE_UBICACIONES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        STATUS DEFAULT
        DATA "geometry from (select p.gid,p.geometry, c.no_cuenta,c.ds_letra,c.no_serie_radio_frecuencia from predios p,mv_medidores_rf m, k_medidor_marca c where p.gid=m.npredio and m.cuenta=c.no_cuenta) as tmp using unique gid using srid=32614"
        TYPE polygon
        LABELCACHE OFF
        CLASSITEM "ds_letra"
        CLASS
            NAME "MEDIDORES BADGER S/R"
            EXPRESSION "A"
            STYLE
                SIZE 10
                COLOR 78 216 180
                OUTLINECOLOR 100 100 190
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES BADGER RADIO 1"
            EXPRESSION "A1"
            STYLE
                SIZE 10
                COLOR 16 16 184
                OUTLINECOLOR 100 100 190
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES BADGER RADIO 3"
            EXPRESSION "A3"
            STYLE
                SIZE 10
                COLOR 27 169 157 
                #COLOR 132 195 190
                OUTLINECOLOR 100 100 190
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES BADGER RADIO 8"
            EXPRESSION "A8"
            STYLE
                SIZE 10
                #COLOR 150 150 255
                COLOR 106 106 171
                OUTLINECOLOR 0 0 255
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 106 106 171
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES ITRON"
            EXPRESSION "P"
            STYLE
                SIZE 10
                COLOR 255 164 32
                OUTLINECOLOR 200 100 32
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 255 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES VEAGN"
            EXPRESSION "U"
            STYLE
                SIZE 10
                COLOR 87 166 57
                OUTLINECOLOR 87 166 57
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 255 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END#CLASS
        CLASS
            NAME "MEDIDORES KAMSTRUP"
            EXPRESSION "X"
            STYLE
                SIZE 10
                COLOR 255 0 0
                OUTLINECOLOR 255 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 255 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES IPERL"
            EXPRESSION "F"
            STYLE
                SIZE 10
                COLOR 128 0 128
                OUTLINECOLOR 255 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 255 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES BOVE"
            EXPRESSION "Y"
            STYLE
                SIZE 10
                COLOR 131 133 131
                OUTLINECOLOR 255 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 255 0
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP